cd /app && cat > /tmp/sim.py <<'EOF'
import json
from archive.hollin import *
from archive import hollin as h
class T:
    def __init__(s, script): s.script=script; s.log=[]
    def now(s): return 1000.0
    def send(s,m,p,hd,b):
        s.log.append((m,p,hd,b if not isinstance(b,bytes) else len(b)))
        return s.script(m,p,hd,b)
def R(st,o): return Response(st,{},json.dumps(o).encode())
state={'n':0}
def srv(m,p,hd,b):
    if m=='POST' and p=='/v3/uploads': return R(201,{'upload_id':'up_1','chunk_size':b['chunk_size'],'expires_at':99999})
    if m=='PUT': return R(200,{'part':int(p.split('/')[-1]),'size':len(b),'etag':'"e%s"'%p.split('/')[-1]})
    if p.endswith('commit'):
        state['n']+=1
        if state['n']==1: return R(409,{'error':{'code':'parts_missing','message':'x','missing':[2]}})
        return R(201,{'file_id':'fl','name':'a','size':1,'checksum':b['checksum']})
t=T(srv)
print(upload_file(t,'a',b'x'*(300*1024),'pro'))
for l in t.log: print(l)
print(h._file_checksum([b'Hollin example part one, ',b'and part two.']))
t=T(srv); upload_file(t,'a',b'','business'); print(t.log)
EOF
